// ═══ KOS TELEMETRY VECTORIZER — Prometheus → Qdrant ═══
// Transforme les métriques brutes Prometheus en vecteurs de performance
// pour le stockage dans Qdrant (6333), alimentant le pipeline
// d'auto-apprentissage KOS.

const latencyData = $input.all()[0]?.json || {};
const memoryData = $input.all()[1]?.json || {};
const healthData = $input.all()[2]?.json || {};

const now = new Date().toISOString();
const vectors = [];

// 1. Extraire les métriques de latence API Gateway
if (latencyData.data?.result) {
  for (const series of latencyData.data.result) {
    const le = series.metric?.le || 'unknown';
    const values = series.values || [];
    const latest = values.length > 0 ? parseFloat(values[values.length - 1][1]) : 0;
    vectors.push({
      id: `telemetry-latency-${le}-${Date.now()}`,
      vector: {
        latency_bucket_le: parseFloat(le) || 0,
        cumulative_count: latest,
        timestamp_unix: Date.now() / 1000
      },
      payload: {
        type: 'prometheus_latency',
        metric: 'nginx_http_request_duration_seconds',
        bucket_le: le,
        value: latest,
        timestamp: now,
        source: 'prometheus:9090'
      }
    });
  }
}

// 2. Extraire les métriques de mémoire des conteneurs
if (memoryData.data?.result) {
  for (const series of memoryData.data.result) {
    const container = series.metric?.container_name || series.metric?.name || 'unknown';
    const values = series.values || [];
    const latest = values.length > 0 ? parseFloat(values[values.length - 1][1]) : 0;
    const memoryMB = Math.round(latest / (1024 * 1024));
    vectors.push({
      id: `telemetry-memory-${container.replace(/[^a-zA-Z0-9]/g, '_')}-${Date.now()}`,
      vector: {
        memory_bytes: latest,
        memory_mb: memoryMB,
        timestamp_unix: Date.now() / 1000
      },
      payload: {
        type: 'prometheus_memory',
        metric: 'container_memory_usage_bytes',
        container: container,
        memory_bytes: latest,
        memory_mb: memoryMB,
        timestamp: now,
        source: 'prometheus:9090'
      }
    });
  }
}

// 3. Extraire les statuts de santé des conteneurs
if (healthData.data?.result) {
  const unhealthyContainers = [];
  for (const series of healthData.data.result) {
    const container = series.metric?.container_name || series.metric?.name || 'unknown';
    const values = series.values || [];
    const latest = values.length > 0 ? parseFloat(values[values.length - 1][1]) : 0;
    if (latest > 0) {
      unhealthyContainers.push(container);
    }
  }
  vectors.push({
    id: `telemetry-health-${Date.now()}`,
    vector: {
      unhealthy_count: unhealthyContainers.length,
      total_components: 14,
      health_ratio: unhealthyContainers.length > 0 ? (14 - unhealthyContainers.length) / 14 : 1.0,
      timestamp_unix: Date.now() / 1000
    },
    payload: {
      type: 'prometheus_health',
      metric: 'container_health_status',
      unhealthy_containers: unhealthyContainers,
      unhealthy_count: unhealthyContainers.length,
      healthy_count: 14 - unhealthyContainers.length,
      health_ratio: unhealthyContainers.length > 0 ? (14 - unhealthyContainers.length) / 14 : 1.0,
      timestamp: now,
      source: 'prometheus:9090'
    }
  });
}

// 4. Ajouter un snapshot système consolidé
vectors.push({
  id: `telemetry-snapshot-${Date.now()}`,
  vector: {
    latency_vectors: vectors.filter(v => v.payload?.type === 'prometheus_latency').length,
    memory_vectors: vectors.filter(v => v.payload?.type === 'prometheus_memory').length,
    health_ratio: vectors.find(v => v.payload?.type === 'prometheus_health')?.payload?.health_ratio || 1.0,
    timestamp_unix: Date.now() / 1000
  },
  payload: {
    type: 'telemetry_snapshot',
    total_vectors: vectors.length,
    metrics_collected: ['latency', 'memory', 'health'],
    timestamp: now,
    source: 'n8n-telemetry-pipeline'
  }
});

return vectors;

// ═══ KOS STRATEGIC INSIGHT SYNTHESIZER v2.0 ═══
// Synthesize strategic insights from 6 data sources:
//   [0] Existing Memories (Supabase)
//   [1] Audit Logs (Supabase)
//   [2] Remediation Logs (Supabase)
//   [3] Prometheus Latency (n8n)
//   [4] Prometheus Memory (n8n)
//   [5] Prometheus Health (n8n)

const existingMemories = $input.all()[0]?.json || [];
const auditLogs = $input.all()[1]?.json || [];
const remediations = $input.all()[2]?.json || [];
const promLatency = $input.all()[3]?.json || {};
const promMemory = $input.all()[4]?.json || {};
const promHealth = $input.all()[5]?.json || {};

const memories = [];
const now = new Date().toISOString();

// 1. Audit pattern detection (existing)
const criticalEvents = Array.isArray(auditLogs) ? auditLogs.filter(l => l.severity === 'critical').length : 0;
const warningEvents = Array.isArray(auditLogs) ? auditLogs.filter(l => l.severity === 'warning').length : 0;
if (criticalEvents > 0) {
  memories.push({
    memory_type: 'insight',
    title: `Audit Pattern: ${criticalEvents} critical + ${warningEvents} warning events in last batch`,
    content: JSON.stringify({
      critical_count: criticalEvents,
      warning_count: warningEvents,
      sample_events: Array.isArray(auditLogs) ? auditLogs.filter(l => l.severity === 'critical').slice(0, 3).map(e => e.event) : [],
    }),
    tags: ['audit', 'pattern', 'critical'],
    source: 'n8n-memory-sync',
    confidence: 0.9,
    context_ref: `audit-batch-${Date.now()}`,
  });
}

// 2. Remediation progress insight (existing)
const recentRemediations = Array.isArray(remediations) ? remediations.filter(r => {
  const created = new Date(r.created_at);
  return (Date.now() - created.getTime()) < 7 * 24 * 3600 * 1000;
}) : [];
if (recentRemediations.length > 0) {
  memories.push({
    memory_type: 'learning',
    title: `Remediation Velocity: ${recentRemediations.length} remediations in last 7 days`,
    content: JSON.stringify({
      count: recentRemediations.length,
      types: [...new Set(recentRemediations.map(r => r.action_type || 'unknown'))],
    }),
    tags: ['remediation', 'learning', 'velocity'],
    source: 'n8n-memory-sync',
    confidence: 0.85,
    context_ref: `remediation-batch-${Date.now()}`,
  });
}

// 3. Prometheus Telemetry Insight — API Gateway Latency
const latencyResults = promLatency.data?.result || [];
if (latencyResults.length > 0) {
  const p95Bucket = latencyResults.find(r => parseFloat(r.metric?.le) >= 0.2);
  const latencyFlag = p95Bucket ? 'normal' : 'elevated';
  memories.push({
    memory_type: 'telemetry',
    title: `API Gateway Latency Scan — ${latencyFlag === 'normal' ? 'Normal' : '⚠️ Elevated'} (${now})`,
    content: JSON.stringify({
      buckets_analyzed: latencyResults.length,
      status: latencyFlag,
      source: 'prometheus:9090',
      metric: 'nginx_http_request_duration_seconds',
    }),
    tags: ['telemetry', 'prometheus', 'latency', 'api-gateway'],
    source: 'n8n-telemetry-pipeline',
    confidence: 0.92,
    context_ref: `telemetry-latency-${Date.now()}`,
  });
}

// 4. Prometheus Telemetry Insight — Container Memory
const memoryResults = promMemory.data?.result || [];
if (memoryResults.length > 0) {
  const highMemoryContainers = memoryResults.filter(r => {
    const vals = r.values || [];
    const latest = vals.length > 0 ? parseFloat(vals[vals.length - 1][1]) : 0;
    return latest > 900 * 1024 * 1024; // > 900 MB
  });
  if (highMemoryContainers.length > 0) {
    memories.push({
      memory_type: 'telemetry',
      title: `⚠️ High Memory Usage: ${highMemoryContainers.length} containers > 900MB`,
      content: JSON.stringify({
        high_memory_containers: highMemoryContainers.map(r => r.metric?.container_name || r.metric?.name || 'unknown'),
        threshold_mb: 900,
        source: 'prometheus:9090',
      }),
      tags: ['telemetry', 'prometheus', 'memory', 'warning'],
      source: 'n8n-telemetry-pipeline',
      confidence: 0.88,
      context_ref: `telemetry-memory-${Date.now()}`,
    });
  }
}

// 5. Prometheus Telemetry Insight — Container Health
const healthResults = promHealth.data?.result || [];
const unhealthyContainers = healthResults.filter(r => {
  const vals = r.values || [];
  return vals.length > 0 && parseFloat(vals[vals.length - 1][1]) > 0;
});
if (unhealthyContainers.length > 0) {
  memories.push({
    memory_type: 'telemetry',
    title: `🚨 Unhealthy Containers Detected: ${unhealthyContainers.length}`,
    content: JSON.stringify({
      unhealthy: unhealthyContainers.map(r => r.metric?.container_name || r.metric?.name || 'unknown'),
      total_components: 14,
      health_ratio: (14 - unhealthyContainers.length) / 14,
      source: 'prometheus:9090',
    }),
    tags: ['telemetry', 'prometheus', 'health', 'critical'],
    source: 'n8n-telemetry-pipeline',
    confidence: 0.95,
    context_ref: `telemetry-health-${Date.now()}`,
  });
}

// 6. Consolidated system state with telemetry
const healthRatio = unhealthyContainers.length > 0 ? (14 - unhealthyContainers.length) / 14 : 1.0;
memories.push({
  memory_type: 'context',
  title: `System State Snapshot (with Telemetry) — ${now}`,
  content: JSON.stringify({
    total_memories: Array.isArray(existingMemories) ? existingMemories.length : 0,
    total_audit_logs: Array.isArray(auditLogs) ? auditLogs.length : 0,
    total_remediations: Array.isArray(remediations) ? remediations.length : 0,
    telemetry_sources: ['prometheus_latency', 'prometheus_memory', 'prometheus_health'],
    containers_monitored: 14,
    health_ratio: healthRatio,
    critical_rate: Array.isArray(auditLogs) && auditLogs.length > 0 ? (criticalEvents / auditLogs.length * 100).toFixed(1) + '%' : '0%',
  }),
  tags: ['system', 'snapshot', 'health', 'telemetry'],
  source: 'n8n-memory-sync-v2',
  confidence: 0.95,
  context_ref: `snapshot-${Date.now()}`,
});

return memories;
